    border-radius: 0.25rem;
    font-size: 0.85rem;
}

::deep .add-task-form-actions {
    display: flex;
    gap: 0.5rem;
}

::deep .btn-save {
    flex: 1;
    padding: 0.4rem;
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 0.25rem;
    cursor: pointer;
}

::deep .btn-save:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

::deep .btn-cancel {
    flex: 1;
    padding: 0.4rem;
    background: #f8f9fa;
    border: 1px solid #ddd;
    border-radius: 0.25rem;
    cursor: pointer;
}

